import React, { ChangeEvent } from 'react';

import { SportsLib } from '@sports-alliance/sports-lib';
import clsx from 'clsx';
import * as L from 'leaflet';
import { useNavigate } from 'react-router-dom';

import getColor from '@helpers/colorsHelper';
import { getSQLDate } from '@helpers/dateHelper';
import { encodePolyline } from '@helpers/gpsHelper';
import {
  getArrayFromBounds,
  getDefaultTileLayer,
  getMap,
  setDefaultMapView,
} from '@helpers/leafletHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohSelect from '@ui-kit/Select';

import { parseStringAsGPX } from '../../Routes/@helpers/gpxParse.heplper';
import { tryDefineWorkoutTypeByKeyword } from '../@helpers/workouts.helper';
import { addWorkoutAsync, getWorkoutTypes } from '../@services/workouts.service';
import { IWorkoutAddDto } from '../@types/DTO/workouts.dto.types';
import { IWorkoutType } from '../@types/workouts.types';

interface IWorkoutNewProps {}

const WorkoutNew: React.FC<IWorkoutNewProps> = () => {
  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);

  const layerGroupRef = React.useRef(L.featureGroup());

  const navigate = useNavigate();
  const [formData, setFormData] = React.useState<IWorkoutAddDto>({
    name: '',
    description: '',
    trackdata: '',
    trackmeta: '',
    date_start: '',
    date_finish: '',
    activity_type: 'sport',
    workout_type: 3,
    bounds: '',
    distance: 0,
    alt_ascent: 0,
    alt_descent: 0,
    alt_max: 0,
    alt_min: 0,
    alt_avg: 0,
    speed_max: 0,
    speed_min: 0,
    speed_avg: 0,
    hr_max: null,
    hr_min: null,
    hr_avg: null,
    temp_max: null,
    temp_min: null,
    temp_avg: null,
    time_mooving: 0,
    time_pause: 0,
  });

  const [types, setTypes] = React.useState<IWorkoutType[]>([]);

  const [isLoading, setIsLoading] = React.useState(true);
  const [loadingError, setLoadingError] = React.useState<Error>();

  const [isParsing, setIsParsing] = React.useState(false);
  const [parsingError, setParsingError] = React.useState<Error>();

  const [isSaving, setIsSaving] = React.useState(false);
  const [savingError, setSavingError] = React.useState<Error>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const dt = await getWorkoutTypes();
        setTypes(dt);
      } catch (error) {
        setLoadingError(error as Error);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  React.useEffect(() => {
    if (!mapContainerRef.current) return;
    if (!mapRef.current) {
      mapRef.current = getMap(mapContainerRef.current as HTMLElement, {
        fullscreenControl: true,
      });
      getDefaultTileLayer().addTo(mapRef.current);

      setDefaultMapView(mapRef.current);

      layerGroupRef.current.addTo(mapRef.current);
    }

    layerGroupRef.current.clearLayers();
  }, []);

  const handleInputChange =
    <K extends keyof IWorkoutAddDto>(field: keyof IWorkoutAddDto) =>
    (value: IWorkoutAddDto[K]) => {
      setFormData((fd) => ({
        ...(fd as IWorkoutAddDto),
        [field]: value,
      }));
    };

  const submitFormHandler = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setIsSaving(true);
      const res = await addWorkoutAsync(formData);
      notificationHelper.success('Тренировка загружена');
      navigate(`/workouts/${res.id}`);
    } catch (er) {
      setSavingError(er as Error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleFileChange = async (_: any, e: ChangeEvent<HTMLInputElement>) => {
    try {
      setIsParsing(true);
      const inputEl = e.target as HTMLInputElement;

      if (!inputEl.files?.length) throw new Error('Не удалось обнаружить корректный файл');

      const gpxFile = inputEl.files[0];

      if (!gpxFile) throw new Error('Не удалось обнаружить корректный файл');
      const gpxString = await gpxFile.text();

      const trackDataRaw: [number, number, number][] = [];
      const metaDataRaw: [number, number, number][] = [];

      const gpx = parseStringAsGPX(gpxString);
      const sportsLibData = await SportsLib.importFromGPX(gpxString, DOMParser);

      let prevTime = 0;

      gpx.trk.forEach((trk, trkIndex) => {
        trk.trkseg.forEach((trkseg, segIndex) => {
          const polylinePoints: Array<[number, number]> = [];
          trkseg.trkpt.forEach((trkpt) => {
            trackDataRaw.push([trkpt.lat, trkpt.lon, trkpt.ele ?? 0]);
            const dateTS = Math.floor(new Date(trkpt.time ?? '').getTime() / 1000);
            metaDataRaw.push([
              prevTime > 0 ? dateTS - prevTime : 0,
              trkpt.hr ?? 0,
              trkpt.atemp ?? -127,
            ]);
            prevTime = dateTS;
            polylinePoints.push([trkpt.lat, trkpt.lon]);
          });

          new L.Polyline(polylinePoints, { color: getColor(trkIndex + segIndex) }).addTo(
            layerGroupRef.current,
          );
        });
      });

      const sportStats = sportsLibData.getStats();

      const name =
        gpx.metadata?.name ??
        (gpx.trk
          .map((trk) => trk?.name)
          .filter(Boolean)
          .join('') ||
          gpx.creator ||
          gpxFile.name ||
          '');

      const description =
        gpx.metadata?.desc ??
        (gpx.trk
          .map((trk) => trk?.description)
          .filter(Boolean)
          .join('') ||
          gpx.creator ||
          '');

      const trackStat: Partial<IWorkoutAddDto> = {
        name,
        description,
        workout_type:
          tryDefineWorkoutTypeByKeyword(
            gpx.trk
              .map((trk) => trk?.type)
              .filter(Boolean)
              .join(''),
          ) ??
          tryDefineWorkoutTypeByKeyword(name) ??
          tryDefineWorkoutTypeByKeyword(description) ??
          3,
        bounds: JSON.stringify(getArrayFromBounds(layerGroupRef.current.getBounds())),
        date_start: getSQLDate(sportsLibData.startDate),
        date_finish: getSQLDate(sportsLibData.endDate),
        activity_type: sportsLibData.getActivityTypesAsString(),
        distance: Math.round(sportsLibData.getDistance().getValue()),
        alt_ascent: Math.round(sportStats.get('Ascent')?.getValue() as number),
        alt_descent: Math.round(sportStats.get('Descent')?.getValue() as number),
        alt_max: Math.round(sportStats.get('Maximum Altitude')?.getValue() as number),
        alt_min: Math.round(sportStats.get('Minimum Altitude')?.getValue() as number),
        alt_avg: Math.round(sportStats.get('Average Altitude')?.getValue() as number),
        speed_max: Math.round(
          (sportStats.get('Maximum speed in kilometers per hour')?.getValue() as number) * 10,
        ),
        speed_min: Math.round(
          (sportStats.get('Minimum speed in kilometers per hour')?.getValue() as number) * 10,
        ),
        speed_avg: Math.round(
          (sportStats.get('Average speed in kilometers per hour')?.getValue() as number) * 10,
        ),
        time_mooving: Math.round(sportStats.get('Moving time')?.getValue() as number),
        time_pause: Math.round(sportStats.get('Pause Time')?.getValue() as number),
      };

      if (sportStats.get('Average Heart Rate')?.getValue() as number) {
        Object.assign(trackStat, {
          hr_max: Math.round(sportStats.get('Maximum Heart Rate')?.getValue() as number),
          hr_min: Math.round(sportStats.get('Minimum Heart Rate')?.getValue() as number),
          hr_avg: Math.round(sportStats.get('Average Heart Rate')?.getValue() as number),
        });
      }

      if (sportStats.get('Average Temperature')?.getValue() as number) {
        Object.assign(trackStat, {
          temp_max: Math.round(sportStats.get('Maximum Temperature')?.getValue() as number),
          temp_min: Math.round(sportStats.get('Minimum Temperature')?.getValue() as number),
          temp_avg: Math.round(sportStats.get('Average Temperature')?.getValue() as number),
        });
      }

      setFormData((cur) => ({
        ...cur,
        trackdata: encodePolyline(trackDataRaw),
        trackmeta: encodePolyline(metaDataRaw),
        ...trackStat,
      }));
      mapRef.current?.fitBounds(layerGroupRef.current.getBounds());
    } catch (error) {
      setParsingError(error as Error);
      console.error(error);
    } finally {
      setIsParsing(false);
    }
  };

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            { href: `/workouts/new`, text: 'Добавление тренировки', active: true },
          ]}
        />
        <PohContainer>
          <PohRow>
            <PohCol sm={12}>
              <h3 className="mb-3">Новая тренировка</h3>
            </PohCol>
          </PohRow>
          <PohRow>
            <PohCol>
              <div>
                {!formData.trackdata && (
                  <PohRow className="mb-2">
                    <PohCol sm={12}>
                      <PohInput
                        type={InputTypes.file}
                        accept={'.gpx'}
                        horizontal
                        label="GPX-трек"
                        placeholder="Загрузить трек"
                        name="workout-file"
                        id="workout-file"
                        onChange={handleFileChange}
                        message={
                          parsingError ? (
                            <small className="text-danger">{parsingError.message}</small>
                          ) : (
                            <small className="float-end">
                              <a
                                href="https://xneek.github.io/gpx-edit/"
                                target="_blank"
                                rel="noreferrer"
                              >
                                open track editor
                              </a>
                            </small>
                          )
                        }
                        disabled={!types || isLoading || isParsing || isSaving}
                      />
                    </PohCol>
                  </PohRow>
                )}
                {formData.trackdata && (
                  <form
                    onSubmit={submitFormHandler}
                    className={clsx('mt-4', 'qa-hiking-base-info-form')}
                  >
                    <PohRow className="mb-2">
                      <PohCol sm={12}>
                        <PohSelect
                          horizontal
                          label="Тип"
                          placeholder="Тип тренировки"
                          required
                          value={formData.workout_type}
                          name="workout-type"
                          id="workout-type"
                          allowEmpty
                          options={
                            types ? types.map(({ id, name }) => ({ label: name, value: id })) : []
                          }
                          onChange={handleInputChange('workout_type')}
                          disabled={!types || isLoading || isParsing || isSaving || !!loadingError}
                        />
                      </PohCol>
                    </PohRow>
                    <PohRow className="mb-2">
                      <PohCol sm={12}>
                        <PohInput
                          horizontal
                          label="Название"
                          placeholder="Название тренировки"
                          required
                          value={formData.name}
                          name="workout-name"
                          autoComplete="workout-name"
                          id="workout-name"
                          onChange={handleInputChange('name')}
                          autoFocus
                          disabled={!types || isLoading || isParsing || isSaving}
                        />
                      </PohCol>
                    </PohRow>
                    <PohRow className="mb-2">
                      <PohCol sm={12}>
                        <PohInput
                          horizontal
                          type={InputTypes.textarea}
                          label="Описание"
                          placeholder="Краткое описание тренировки"
                          value={formData.description}
                          name="workout-desc"
                          autoComplete="workout-desc"
                          id="workout-desc"
                          onChange={handleInputChange('description')}
                          disabled={!types || isLoading || isParsing || isSaving}
                        />
                      </PohCol>
                    </PohRow>

                    <PohRow className="mb-4 mt-2">
                      <PohCol sm={2} />
                      <PohCol sm={10}>
                        {savingError && <PohAlert>{savingError.message}</PohAlert>}
                        <PohButton
                          disabled={isLoading || isParsing || isSaving}
                          variant={ButtonVariant.Primary}
                          className="w-100"
                          type="submit"
                        >
                          Сохранить
                        </PohButton>
                      </PohCol>
                    </PohRow>
                  </form>
                )}
              </div>
            </PohCol>
            <PohCol sm={4}>
              <div ref={mapContainerRef} style={{ aspectRatio: '1' }} />
            </PohCol>
          </PohRow>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutNew;
